/// The counts as one line of JSON, e.g. `{"lines":2,"words":3}`.
pub fn to_json(counts: &Counts) -> String {
    format!("{{\"lines\": {}, \"words\": {}}}", counts.lines, counts.words)
}

fn usage() -> ! {
    eprintln!("usage: toolbox stats [--json] <file>");

if json {
    println!("{}", to_json(&counts));
} else {
    println!("lines: {}", counts.lines);
    println!("words: {}", counts.words);
}

let json = args.iter().any(|a| a == "--json");
let rest: Vec<&String> = args.iter().filter(|a| *a != "--json").collect();
if rest.len() == 2 && rest[0] == "stats" {
    run_stats(rest[1], json);
} else {

    assert_eq!(count("one two\nthree\n"), Counts { lines: 2, words: 3 });
}

#[test]
fn formats_counts_as_json() {
    let counts = Counts { lines: 2, words: 3 };
    assert_eq!(to_json(&counts), "{\"lines\":2,\"words\":3}");
}
